///////// 4. 서브미션 콜백 영역 /////////
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_dep_usr",
        action : "/depusr.do",
        ref : "",
        target : "MxDataSet_dep_usr=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    scwin.listSyncHeader();
    scwin.listSyncPart();
    scwin.listSyncTeam();
};

