scwin.formchrgteamSave = async function() {
    if (!scwin.cntDatasetRowCheck(MxDataSet_chrgteam)) {
        MxLogicalTr_team.KeyName = "toinb_dataid4";

        const sbmOptions = {
            id : "sbm_MxLogicalTr_team",
            action : "/formchrgteam.do",
            ref : "MxDataSet_chrgteam",
            target : "MxLogicalTr_team=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    } else {
        alert("저장하시려면 체크박스를 해제해주십시요\n체크는 삭제에만 사용됩니다");
    }
};

///////// 5. 일반/업무 함수 영역 /////////
 // 팀에서 선택한 값
// var jfilterMenu = "";//권한의 종류(업무)에 따라 화면메뉴필터
scwin.InfoMenuID = function() {
    // TODO Stage2: $c.frame 대체 불가(형제/절대 프레임 접근) — 프레임 구조 재설계 필요
    let e = $c.frame.path("/pageIndex").selPageID;
    e = e.split("_");
    const myStr = e[1];
    return myStr;
};

scwin.listDelete = function(sval) {
    if (!scwin.cntDatasetRowCheck(sval)) {
        alert("체크사항이 없습니다.");
    } else {
        for (let i = sval.getRowCount() - 1; i >= 0; i--) {
            if (sval.getCellData(i, "CHK_FLAG") === 1) {
                sval.removeRow(i);
            }
        }
    }
};

scwin.formAddToTeam = function() {
    if (!scwin.cntDatasetRowCheck(MxDataSet_form)) {
        alert('체크사항이 없습니다');
        return;
    }
    // alert(MxDataSet_chrgteam.CountRow);

    const rsltM = "";
    // if (MxDataSet_chrgteam.CountRow == 0) {
    //	MxDataSet_chrgteam.addRow();
    // }
    const team_cd = MxDataSet_dep_team.getCellData(MxCombo_team.getSelectedIndex() + 1, "dep_cd");
    // alert(MxDataSet_chrgteam.CountRow);
    // return;
    // TODO Stage2: 0-based 인덱스 검토(비정형 루프 — 토큰만 치환)
    for (i = 1; i <= MxDataSet_form.getRowCount(); i++) {
        if (MxDataSet_form.getCellData(i, "CHK_FLAG") === 1) {
            const f_cd = MxDataSet_form.getCellData(i, "FORM_CD");
            const f_nm = MxDataSet_form.getCellData(i, "FORM_KOR_NM");
            // if (  fn_dupleChek(team_cd, f_cd) == "N") {

            if (MxDataSet_chrgteam.getRowCount() === 0) {
                MxDataSet_chrgteam.insertRow();
                MxDataSet_chrgteam.setCellData(MxDataSet_chrgteam.getFocusedRowIndex(), "DEP_CD", team_cd);
                MxDataSet_chrgteam.setCellData(MxDataSet_chrgteam.getFocusedRowIndex(), "DEP_NM", MxCombo_team.text);
                MxDataSet_chrgteam.setCellData(MxDataSet_chrgteam.getFocusedRowIndex(), "FORMISUR_CD", f_cd);
                MxDataSet_chrgteam.setCellData(MxDataSet_chrgteam.getFocusedRowIndex(), "FORM_KOR_NM", f_nm);
                MxDataSet_chrgteam.setCellData(MxDataSet_chrgteam.getFocusedRowIndex(), "ASSGN_END_DD", MxDataSet_form.getCellData(i, "END_DD"));
                MxDataSet_chrgteam.setCellData(MxDataSet_chrgteam.getFocusedRowIndex(), "ASSGN_STRT_DD", MxDataSet_form.getCellData(i, "STRT_DD"));
            } else {
                MxDataSet_chrgteam.insertRow(MxDataSet_chrgteam.getFocusedRowIndex() + 1);
                MxDataSet_chrgteam.setCellData(MxDataSet_chrgteam.getFocusedRowIndex(), "DEP_CD", team_cd);
                MxDataSet_chrgteam.setCellData(MxDataSet_chrgteam.getFocusedRowIndex(), "DEP_NM", MxCombo_team.text);
                MxDataSet_chrgteam.setCellData(MxDataSet_chrgteam.getFocusedRowIndex(), "FORMISUR_CD", f_cd);
                MxDataSet_chrgteam.setCellData(MxDataSet_chrgteam.getFocusedRowIndex(), "FORM_KOR_NM", f_nm);
                MxDataSet_chrgteam.setCellData(MxDataSet_chrgteam.getFocusedRowIndex(), "ASSGN_END_DD", MxDataSet_form.getCellData(i, "END_DD"));
                MxDataSet_chrgteam.setCellData(MxDataSet_chrgteam.getFocusedRowIndex(), "ASSGN_STRT_DD", MxDataSet_form.getCellData(i, "STRT_DD"));
            }
            // }else{
            //	rsltM += f_cd + " " + f_nm + "\n";
            // }
            MxDataSet_form.setCellData(i, "CHK_FLAG", 0);
        }
    }
    // if (rsltM != "") {

    //	alert("다음 서식은 이미 추가 되어 있습니다.\n" + rsltM);

    // }

};

scwin.dupleChek = function(sval1) {
    // sval1 : col
    // sval2 : FORM_CD
    // sval0 : 
    const sval0 = MxDataSet_dep_team.getCellData(MxCombo_team.getSelectedIndex() + 1, "dep_cd");
    const sval2 = MxDataSet_form.getCellData(sval1, "FORM_CD");
    let rtn = "N";
    // TODO Stage2: 0-based 인덱스 검토(비정형 루프 — 토큰만 치환)
    for (i = 1; i <= MxDataSet_chrgteam.getRowCount(); i++) {
        if (MxDataSet_chrgteam.getCellData(i, "DEP_CD") === sval0 && MxDataSet_chrgteam.getCellData(i, "FORMISUR_CD") === sval2) {
            rtn = "Y";
            // break;

        }
    }
    if (rtn === "Y") {
        alert("다음 서식은 이미 추가 되어 있습니다.\n" + MxDataSet_form.getCellData(sval1, "FORM_KOR_NM"));
        MxDataSet_form.setCellData(sval1, "CHK_FLAG", 0);
    }
    // return rtn;

};

scwin.cntDatasetRowCheck = function(sval) {
    // 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다.
    cCnt = 0;
    for (let i = 0; i < sval.getRowCount(); i++) {
        // alert(sval.NameValue(i, "CHK_FLAG"));
        if (sval.getCellData(i, "CHK_FLAG") === 1) {
            cCnt++;
        }
    }
    if (cCnt === 0) {
        return false;
    } else {
        return true;
    }
};

scwin.comboHeader = function(row) {
    scwin.jpart = "0000";
    scwin.jteam = "0000";
    scwin.jheader = MxDataSet_dep_header.getCellData(row, "dep_cd");
    // alert(jheader);

    MxDataSet_dep_part.removeColumnFilterAll();

MxDataSet_dep_team.removeColumnFilterAll();

MxCombo_part.setSelectedIndex(0);
    MxCombo_team.setSelectedIndex(0);

    /*

    MxDataSet_dep_usr.UseFilter = "false";
    grd_userlist.Redraw ="false";

    MxDataSet_dep_usr.UseFilter = "true";

    // TODO Stage2: Gauce Filter() — 규칙 29 필터 재설계(setColumnFilter) 필요
    MxDataSet_dep_usr.Filter();
    MxDataSet_dep_usr.SortExpr="+NO";
    MxDataSet_dep_usr.Sort();
    grd_userlist.Redraw ="true";
    */
    // MxDataSet_dep_usr.Rowposition = 10; 
    // MxDataSet_dep_usr.Rowposition = 1;

};

scwin.comboPart = function(row) {
    scwin.jteam = "0000";
    if (MxCombo_header.getSelectedIndex() === 0 && MxCombo_part.getSelectedIndex() !== 0) {
        alert("본부를 먼저 선택하세요.");
        MxCombo_part.setSelectedIndex(0);
    } else {
        if (MxCombo_part.getSelectedIndex() === 0) {
            MxCombo_team.setSelectedIndex(0);
        }
        scwin.jpart = MxDataSet_dep_part.getCellData(row, "dep_cd");

        MxDataSet_dep_team.removeColumnFilterAll();

/*

        MxDataSet_dep_usr.UseFilter = "false";
        grd_userlist.Redraw ="false";

        MxDataSet_dep_usr.UseFilter = "true";

        // TODO Stage2: Gauce Filter() — 규칙 29 필터 재설계(setColumnFilter) 필요
        MxDataSet_dep_usr.Filter();
        MxDataSet_dep_usr.SortExpr="+NO";
        MxDataSet_dep_usr.Sort();
        grd_userlist.Redraw ="true";
        */
        // MxDataSet_dep_usr.Rowposition = 10; 
        // MxDataSet_dep_usr.Rowposition = 1;

    }
};

scwin.comboTeam = function(row) {
    // alert(jheader + " " +jpart + " " + jteam);
    if (MxCombo_part.getSelectedIndex() === 0 && MxCombo_team.getSelectedIndex() !== 0) {
        alert("부서를 먼저 선택하세요.");
        MxCombo_team.setSelectedIndex(0);
    } else {
        scwin.jteam = MxDataSet_dep_team.getCellData(row, "dep_cd");

        MxDataSet_dep_team.removeColumnFilterAll();

/*

        MxDataSet_dep_usr.UseFilter = "false";
        grd_userlist.Redraw ="false";

        MxDataSet_dep_usr.UseFilter = "true";

        // TODO Stage2: Gauce Filter() — 규칙 29 필터 재설계(setColumnFilter) 필요
        MxDataSet_dep_usr.Filter();
        MxDataSet_dep_usr.SortExpr="+NO";
        MxDataSet_dep_usr.Sort();
        grd_userlist.Redraw ="true";
        MxDataSet_dep_usr.Rowposition = 10; 
        MxDataSet_dep_usr.Rowposition = 1;
        */

    }
};

scwin.usrName = function(keyCode) {

    if (keyCode === 13) on_close();
let cnt = 0;
    const len = txb_userid.getValue().length;
    const txtVal = txb_userid.getValue().toUpperCase();
    if (txtVal === "") {
        MxDataSet_dep_usr.sort("NO", 0);
    } else {
        MxDataSet_dep_usr.sort("EMP_NM", 0);
    }
for (let i = 0; i < MxDataSet_dep_usr.getRowCount(); i++) {
        const name = MxDataSet_dep_usr.getCellData(i, "EMP_NM").substring(0, len).toUpperCase();
        if (txtVal <= name) {
            cnt = i;
            break;
        }
    }
// TODO Stage2: 그리드 포커스 전환 필요(구 MxDataSet_dep_usr.Rowposition = cnt + 9)
    // TODO Stage2: 그리드 포커스 전환 필요(구 MxDataSet_dep_usr.Rowposition = cnt)
};

scwin.listDelete = function(sval) {
    if (!scwin.cntDatasetRowCheck(sval)) {
        alert("체크사항이 없습니다.");
    } else {
        for (let i = sval.getRowCount() - 1; i >= 0; i--) {
            if (sval.getCellData(i, "CHK_FLAG") === 1) {
                sval.removeRow(i);
            }
        }
    }
};

scwin.cntDatasetRowCheck = function(sval) {
    // 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다.
    cCnt = 0;
    for (let i = 0; i < sval.getRowCount(); i++) {
        // alert(sval.NameValue(i, "CHK_FLAG"));
        if (sval.getCellData(i, "CHK_FLAG") === 1) {
            cCnt++;
        }
    }
    if (cCnt === 0) {
        return false;
    } else {
        return true;
    }
};

scwin.undo = function(sval) {
    sval.undoAll();
};

